/**
 * Shared client-side profile completion calculator.
 * Weights must stay in sync with backend services/profileCompleteness.js
 */

export const PROFILE_COMPLETION_WEIGHTS = {
  personalInformation: 15,
  contactInformation: 15,
  education: 15,
  experience: 15,
  skills: 10,
  resumeUploaded: 15,
  currentSalary: 7.5,
  expectedSalary: 7.5,
};

const isFilled = (value) => {
  if (value === null || value === undefined) return false;
  if (typeof value === "string") return value.trim() !== "";
  if (typeof value === "number") return !Number.isNaN(value);
  if (Array.isArray(value)) return value.length > 0;
  return Boolean(value);
};

export const calculateProfileCompleteness = (candidate = {}) => {
  const professional = candidate.professional || {};
  let score = 0;

  if (isFilled(candidate.firstname) && isFilled(candidate.lastname)) {
    score += PROFILE_COMPLETION_WEIGHTS.personalInformation;
  }
  if (isFilled(candidate.mobile) && isFilled(candidate.email)) {
    score += PROFILE_COMPLETION_WEIGHTS.contactInformation;
  }
  if (isFilled(professional.highestQualification)) {
    score += PROFILE_COMPLETION_WEIGHTS.education;
  }
  if (isFilled(professional.experienceInyear)) {
    score += PROFILE_COMPLETION_WEIGHTS.experience;
  }
  if (isFilled(professional.skill)) {
    score += PROFILE_COMPLETION_WEIGHTS.skills;
  }
  if (isFilled(candidate.resume)) {
    score += PROFILE_COMPLETION_WEIGHTS.resumeUploaded;
  }
  if (isFilled(professional.currentSalary)) {
    score += PROFILE_COMPLETION_WEIGHTS.currentSalary;
  }
  if (isFilled(professional.expectedsalary)) {
    score += PROFILE_COMPLETION_WEIGHTS.expectedSalary;
  }

  const profileCompleteness = Math.round(score);
  return {
    profileCompleteness,
    profileCompletenessLabel: `${profileCompleteness}% Complete`,
  };
};

export default calculateProfileCompleteness;
